// Staged funnel with budgets enforced (plain JS)
function funnel(firstStage, rerank, kRecall = 200, kRerank = 50, kGen = 5) {
  return async (query) => {
    const recalled = (await firstStage(query)).slice(0, kRecall);
    const reranked = (await rerank(query, recalled.slice(0, kRerank)));
    return reranked.slice(0, kGen); // generation sees 5, never 500
  };
}
// Budgets are parameters, not accidents: kRerank bounds the expensive calls.

