function funnelStages(recalled, rerankScores, kRerank, kGen) {
  const top = recalled.slice(0, kRerank);
  const reranked = top.map((id) => ({ id, s: rerankScores[id] || 0 })).sort((a, b) => b.s - a.s);
  return reranked.slice(0, kGen).map((r) => r.id);
}
const recalled = ['c1', 'c2', 'c3', 'c4', 'c5', 'c6'];
const scores = { c1: 0.2, c2: 0.9, c3: 0.5, c4: 0.8, c5: 0.1, c6: 0.7 };
console.log(funnelStages(recalled, scores, 4, 2).join(','));
console.log('rerank calls: 4, generation chunks: 2');

